def clean_filename(fname: str) -> str:
    if not fname:
        return ""
    if "_" in fname and len(fname.split("_")[0]) == 8:
        return "_".join(fname.split("_")[1:])
    return fname


def clean_ai_content(content: str) -> str:
    if not content:
        return ""
    # Strip raw [Source: ...] brackets if generated by LLM
    text = re.sub(r'\[Source:\s*[^\]]+\]', '', content, flags=re.IGNORECASE)
    # Convert markdown **bold** to <strong>bold</strong>
    text = re.sub(r'\*\*(.*?)\*\*', r'<strong>\1</strong>', text)
    # Convert markdown *italic* to <em>italic</em>
    text = re.sub(r'\*(.*?)\*', r'<em>\1</em>', text)
    # Replace newlines with <br>
    text = text.replace('\n', '<br>').strip()
    return text


