def create_svg_sparkline(y_values, width=240, height=60):
    if not y_values:
        return ""
    min_y, max_y = 0, 100
    n = len(y_values)
    if n == 1:
        y_values = [y_values[0], y_values[0]]
        n = 2
    points = []
    for i, val in enumerate(y_values):
        x = (i / max(1, n - 1)) * width
        y = height - ((val - min_y) / max(1, max_y - min_y)) * (height - 8) - 4
        points.append((x, y))

    path_d = f"M {points[0][0]:.1f},{points[0][1]:.1f} " + " ".join(f"L {px:.1f},{py:.1f}" for px, py in points[1:])
    fill_d = f"{path_d} L {width:.1f},{height:.1f} L 0,{height:.1f} Z"
    dots_html = "".join(f'<circle cx="{px:.1f}" cy="{py:.1f}" r="3" fill="#2563eb" />' for px, py in points)

    return f"""
    <svg width="100%" height="{height}" viewBox="0 0 {width} {height}" preserveAspectRatio="none" style="display:block;margin-top:6px;">
        <path d="{fill_d}" fill="rgba(37,99,235,0.12)" />
        <path d="{path_d}" fill="none" stroke="#2563eb" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" />
        {dots_html}
    </svg>
    """


def create_svg_donut(values, colors, size=75, stroke_width=14):
    total = sum(values) or 1
    radius = (size - stroke_width) / 2
    circumference = 2 * 3.14159265 * radius
    cx = cy = size / 2

    if len(values) == 1:
        color = colors[0]
        return f"""
        <svg width="{size}" height="{size}" viewBox="0 0 {size} {size}" style="display:block;margin:6px auto 2px auto;">
            <circle cx="{cx}" cy="{cy}" r="{radius}" fill="none" stroke="{color}" stroke-width="{stroke_width}" />
        </svg>
        """

    accum_pct = 0.0
    segments_html = []
    for val, color in zip(values, colors):
        pct = val / total
        dash_len = pct * circumference
        gap_len = circumference - dash_len
        offset = -(accum_pct * circumference)
        segments_html.append(
            f'<circle cx="{cx}" cy="{cy}" r="{radius}" fill="none" stroke="{color}" stroke-width="{stroke_width}" '
            f'stroke-dasharray="{dash_len:.2f} {gap_len:.2f}" stroke-dashoffset="{offset:.2f}" transform="rotate(-90 {cx} {cy})" />'
        )
        accum_pct += pct

    return f"""
    <svg width="{size}" height="{size}" viewBox="0 0 {size} {size}" style="display:block;margin:6px auto 2px auto;">
        {"".join(segments_html)}
    </svg>
    """

